`include "disciplines.vams"
`include "constants.vams"
module paper_vr(ip, im, ref, out);
 inout ip, im, ref, out;
 electrical ip, im, ref, out;

 analog begin
  V(out,ref) <+ 1.5*V(ip,im)-0.125;
 end
endmodule

`include "disciplines.vams"
`include "constants.vams"
module paper_ex(ctl, freq);
 inout ctl, freq;
 electrical ctl, freq;
 real f;
 analog begin
  f=0.4+0.5*V(ctl);
  if (f<0.2) f=0.2;
  else if (f>1.0) f=1.0;
  V(freq) <+ f;
 end
endmodule

`include "disciplines.vams"
`include "constants.vams"
module paper_sh_timer(in, out, count);
 inout in, out, count;
 electrical in, out, count;
 real q,n;
 analog begin
  @(initial_step) begin q=-0.25; n=0; end
  @(timer(2e-6,2e-6,1e-9)) begin q=V(in); n=n+1; end
  V(out)<+q;
  V(count)<+n;
 end
endmodule

`include "disciplines.vams"
`include "constants.vams"
module paper_hc(in, out, count);
 inout in, out, count;
 electrical in, out, count;
 real q,n;
 analog begin
  @(initial_step) begin q=0; n=0; end
  @(cross(V(in)-0.65,+1,1e-9,2e-4)) begin q=1; n=n+1; end
  @(cross(V(in)-0.35,-1,1e-9,2e-4)) begin q=0; n=n+1; end
  V(out)<+0.1+0.8*q;
  V(count)<+n;
 end
endmodule

`include "disciplines.vams"
`include "constants.vams"
module paper_hc_start(in, out, count);
 inout in, out, count;
 electrical in, out, count;
 real q,n;
 analog begin
  @(initial_step) begin q=(V(in)>0.65); n=0; end
  @(cross(V(in)-0.65,+1,1e-9,2e-4)) begin q=1; n=n+1; end
  @(cross(V(in)-0.35,-1,1e-9,2e-4)) begin q=0; n=n+1; end
  V(out)<+0.1+0.8*q;
  V(count)<+n;
 end
endmodule

`include "disciplines.vams"
`include "constants.vams"
module paper_edge(out, state, count);
 inout out, state, count;
 electrical out, state, count;
 real q,n;
 analog begin
  @(initial_step) begin q=0; n=0; end
  @(timer(2e-6,4e-6,1e-9)) begin q=1-q; n=n+1; end
  V(out)<+transition(q,0.25e-6,0.5e-6,1e-6);
  V(state)<+q;
  V(count)<+n;
 end
endmodule

`include "disciplines.vams"
`include "constants.vams"
module paper_idt(ctl, phase);
 inout ctl, phase;
 electrical ctl, phase;
 real p;
 analog begin
  p=idt(V(ctl)/1e-6,0.125);
  V(phase)<+p;
 end
endmodule

`include "disciplines.vams"
`include "constants.vams"
module paper_wrap(phase, out);
 inout phase, out;
 electrical phase, out;
 real p;
 analog begin
  p=idtmod(0.75/1e-6,0.125,1.0,0.0);
  V(phase)<+p;
  V(out)<+sin(2*`M_PI*p);
 end
endmodule

`include "disciplines.vams"
`include "constants.vams"
module paper_cell(in,out,count);
 inout in,out,count; electrical in,out,count;
 parameter real start=2e-6; parameter real period=2e-6; parameter real q0=-0.25;
 real q,n;
 analog begin
 @(initial_step) begin q=q0; n=0; end
 @(timer(start,period,1e-9)) begin q=V(in); n=n+1; end
 V(out)<+q; V(count)<+n;
 end
endmodule
module paper_isolation(a,b,oa,ob,na,nb);
 inout a,b,oa,ob,na,nb; electrical a,b,oa,ob,na,nb;
 paper_cell #(.start(2e-6),.period(2e-6),.q0(-0.25)) A(a,oa,na);
 paper_cell #(.start(3e-6),.period(3e-6),.q0(0.75)) B(b,ob,nb);
endmodule

`include "disciplines.vams"
`include "constants.vams"
module paper_sh_reset(in, clk, reset, out, state, count);
 inout in, clk, reset, out, state, count;
 electrical in, clk, reset, out, state, count;
 real q,n;
 analog begin
  @(initial_step) begin q=-0.25; n=0; end
  @(cross(V(clk)-0.5,+1,1e-9,2e-4) or cross(V(reset)-0.5,+1,1e-9,2e-4)) begin
    n=n+1;
    if(V(reset)>0.25) q=-0.25; else q=V(in);
  end
  V(state)<+q; V(count)<+n;
  V(out)<+transition(q,0,0.1e-6,0.1e-6);
 end
endmodule

`include "disciplines.vams"
`include "constants.vams"
module paper_hc_edge(in, out, state, count);
 inout in, out, state, count;
 electrical in, out, state, count;
 real q,n;
 analog begin
  @(initial_step) begin q=0; n=0; end
  @(cross(V(in)-0.65,+1,1e-9,2e-4)) begin q=1; n=n+1; end
  @(cross(V(in)-0.35,-1,1e-9,2e-4)) begin q=0; n=n+1; end
  V(state)<+q; V(count)<+n;
  V(out)<+0.1+0.8*transition(q,0.125e-6,0.25e-6,0.5e-6);
 end
endmodule

`include "disciplines.vams"
`include "constants.vams"
module paper_vco(ctl, freq, phase, out);
 inout ctl, freq, phase, out;
 electrical ctl, freq, phase, out;
 real f,p;
 analog begin
  f=0.4+0.5*V(ctl);
  if(f<0.2) f=0.2; else if(f>1.0) f=1.0;
  p=idtmod(f/1e-6,0.125,1.0,0.0);
  V(freq)<+f; V(phase)<+p;
  V(out)<+sin(2*`M_PI*p);
 end
endmodule
